'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const numeric = value => value !== null && value !== undefined && Number.isFinite(Number(value));
const fmt = (value, digits = 2) => numeric(value) ? Number(value).toLocaleString('en-US', {minimumFractionDigits: digits, maximumFractionDigits: digits}) : '—';
const money = (value, signed = false) => numeric(value) ? `${Number(value) < 0 ? '−' : signed && Number(value) > 0 ? '+' : ''}$${fmt(Math.abs(Number(value)))}` : '—';
const pct = value => numeric(value) ? `${fmt(value)} %` : '—';
const signClass = value => Number(value) > 0 ? 'gain' : Number(value) < 0 ? 'loss' : '';
const dateObj = value => new Date(typeof value === 'number' ? value < 1e12 ? value * 1000 : value : value);
const date = (value, long = false) => { const d = dateObj(value); return Number.isFinite(d.getTime()) ? d.toLocaleString('es', {timeZone:'UTC',year:'numeric',month:'short',day:'2-digit',...(long ? {hour:'2-digit',minute:'2-digit',hour12:false}: {})}) : '—'; };
const stamp = value => dateObj(value).getTime();
const symbolLabel = value => String(value || 'EURUSD').replace(/^([A-Z]{3})([A-Z]{3})$/, '$1/$2');
const state = {defaults:{}, config:{}, code:'', defaultCode:'', datasets:[], experiments:[], result:null, datasetId:null, busy:false, csv:'', view:'dashboard', mc:null, comparison:null, selectedTrade:null, holdout:null, research:null};
const icons = {
  dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  chart:'<path d="M3 3v18h18M6 15l4-5 4 3 6-7"/>', code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',
  trades:'<path d="M3 7h17l-4-4M21 17H4l4 4M20 7l-4 4M4 17l4-4"/>', shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z"/><path d="m8 12 3 3 5-6"/>',
  sliders:'<path d="M5 3v6m0 4v8M12 3v12m0 4v2M19 3v2m0 4v12M2 9h6m1 6h6m1-10h6"/>', compare:'<path d="M4 5h6v14H4zM14 9h6v10h-6zM3 22h18"/>',
  database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>', flask:'<path d="M9 3h6m-5 0v7L4 20c-.4.7.1 1 1 1h14c1 0 1.4-.3 1-1l-6-10V3M7 15h10"/>',
  bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>', play:'<path d="m8 4 12 8-12 8z"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', upload:'<path d="M12 17V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',
  menu:'<path d="M3 5h18M3 12h18M3 19h18"/>', reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>', info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>', wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 7V4h14v1M16 10h5v6h-5z"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.info}</svg>`;
function hydrateIcons(root = document){ $$('[data-icon]',root).forEach(node => node.innerHTML = icon(node.dataset.icon)); }
function emptyChart(target, message='Ejecuta un backtest para ver los resultados.'){ const el=$(target); if(el) el.innerHTML=`<div class="chart-empty">${icon('chart')}<span>${esc(message)}</span></div>`; }
function status(message='', type='success'){const node=$('#global-status'); node.hidden=!message;node.className=`global-status ${type}`;node.textContent=message;}
async function api(url, payload){const options = payload === undefined ? {} : {method:'POST', headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}; const response=await fetch(url,options);let result;try{result=await response.json();}catch{throw new Error('El servidor local no devolvió una respuesta válida.');}if(!response.ok)throw new Error(result.error||`No se pudo completar la solicitud (${response.status}).`);return result;}
async function task(button, message, work){if(button?.disabled)return;const old=button?.innerHTML;if(button){button.disabled=true;button.setAttribute('aria-busy','true');}status(message,'busy');try{const result=await work();if($('#global-status').classList.contains('busy'))status('Listo. Resultados actualizados.');return result;}catch(error){status(error.message || String(error),'error');return null;}finally{if(button){button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=old;}}}
function go(view){if(!$('#view-'+view))view='dashboard';state.view=view;$$('.view').forEach(n=>n.classList.toggle('active',n.id==='view-'+view));$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#sidebar').classList.remove('open');history.replaceState(null,'','#'+view);if(view==='chart')renderCandles();if(view==='trades')renderTrades();if(view==='dashboard')renderAccountCharts();if(view==='risk'&&state.mc)renderMC(state.mc);if(view==='compare'&&state.comparison)renderComparison(...state.comparison);window.scrollTo({top:0,behavior:'instant'});}
const strategyName = cfg => ({trend:'Tendencia + ruptura',random:'Entradas aleatorias',custom:'Python personalizado'}[cfg?.strategy] || 'Estrategia');
const description = cfg => ({trend:'EMA, fuerza de tendencia y ruptura; cada filtro es configurable.',random:'Control aleatorio con semilla fija y la misma gestión de riesgo.',custom:'Señales definidas por tu código Python, con ejecución del motor.'}[cfg?.strategy]||'');
const configGroups = [
  ['Cuenta y ejecución', [
    ['initial_balance','Capital inicial (USD)', 'number',1,1],['timeframe','Temporalidad de señales','select',[['1m','1 minuto'],['5m','5 minutos'],['15m','15 minutos'],['30m','30 minutos'],['1h','1 hora'],['4h','4 horas'],['1d','1 día']]],
    ['direction','Dirección permitida','select',[['both','Compras y ventas'],['long','Solo compras'],['short','Solo ventas']]],['leverage','Apalancamiento (1 : x)','number',1,1],
    ['trade_start','Operar desde (UTC)','date'],['trade_end','Operar hasta, exclusivo (UTC)','date'],['force_close','Cerrar posición al terminar','bool']]],
  ['Riesgo y tamaño',[
    ['sizing_mode','Tamaño de posición','select',[['risk','Según riesgo porcentual'],['fixed','Unidades fijas']]],['risk_pct','Riesgo por operación (%)','number',0.01,0.01],['fixed_units','Unidades fijas','number',1,1],['reward_risk','Beneficio / riesgo (R)','number',0.1,0.1],
    ['lot_step','Paso de tamaño (unidades)','number',1,1],['min_units','Tamaño mínimo (unidades)','number',1,1],['break_even_r','Mover stop a entrada desde (R, 0 desactiva)','number',0,0.1],['cooldown_bars','Espera tras cierre (velas)','number',0,1]]],
  ['Stops e indicadores',[
    ['stop_mode','Distancia del stop','select',[['atr','Múltiplo de ATR'],['pips','Pips fijos'],['percent','Porcentaje del precio']]],['atr_period','Periodo ATR','number',2,1],['atr_multiplier','Múltiplo ATR','number',0.1,0.1],['stop_pips','Stop fijo (pips)','number',0.1,0.1],['stop_percent','Stop (% del precio)','number',0.01,0.01],
    ['ema_filter','Activar filtro EMA','bool'],['ema_period','Periodo EMA','number',2,1],['adx_filter','Activar filtro ADX','bool'],['adx_period','Periodo ADX','number',2,1],['adx_threshold','ADX mínimo','number',0,1],['daily_filter','Activar tendencia diaria','bool'],['daily_ema_period','Periodo EMA diaria','number',2,1],['breakout_period','Ruptura: ventana (velas)','number',2,1],['breakout_atr_buffer','Margen de ruptura (ATR)','number',0,0.05]]],
  ['Costos y reproducibilidad',[
    ['spread_pips','Spread supuesto (pips)','number',0,0.1],['slippage_pips','Deslizamiento por ejecución (pips)','number',0,0.1],['commission_per_lot_side','Comisión por lote y lado (USD)','number',0,0.1],['swap_per_lot_day','Swap por lote / día (USD)','number',null,0.1],['random_seed','Semilla aleatoria','number',0,1],['random_trade_probability','Probabilidad de señal aleatoria (0–1)','number',0,0.01],['custom_history_limit','Historial visible al código (velas)','number',50,1]]]
];
function renderConfig(){
  $('#strategy-choice').value=state.config.strategy||'trend';$('#strategy-explanation').textContent=description(state.config);$('#code-editor').value=state.code;
  $('#config-groups').innerHTML=configGroups.map(([title,fields])=>`<article class="panel"><div class="panel-heading"><h2>${title}</h2></div><div class="form-grid">${fields.filter(([key])=>key in state.config).map(([key,label,type,min,step])=>{
    const value=state.config[key]; if(type==='bool')return `<label class="toggle-field">${label}<input type="checkbox" data-config="${key}" ${value?'checked':''}></label>`;
    if(type==='select')return `<label>${label}<select data-config="${key}">${min.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select></label>`;
    return `<label>${label}<input data-config="${key}" type="${type}" value="${esc(type==='date'?(value||'').slice(0,10):value)}" ${type==='number'?`${min!==null?`min="${min}"`:''} step="${step}"`:''}></label>`;
  }).join('')}</div></article>`).join('');
  if('custom_params' in state.config)$('#config-groups').insertAdjacentHTML('beforeend','<article class="panel"><div class="panel-heading"><h2>Parámetros propios del código</h2></div><div class="form-body"><label>Objeto JSON · valores numéricos<textarea id="custom-params" rows="3" spellcheck="false"></textarea></label><p class="form-help">Disponibles en ctx["params"]["nombre_del_parametro"].</p></div></article>');
  if($('#custom-params'))$('#custom-params').value=JSON.stringify(state.config.custom_params||{},null,2);
  $$('[data-config]').forEach(el=>el.addEventListener('change',()=>{const key=el.dataset.config;state.config[key]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.type==='date'?(el.value?el.value+'T00:00:00Z':null):el.value;markDirty();}));
}
function readConfig(){
  $$('[data-config]').forEach(el=>{if(!el.checkValidity())throw new Error(`Revisa «${el.closest('label').textContent.trim()}».`);const key=el.dataset.config;state.config[key]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.type==='date'?(el.value?el.value+'T00:00:00Z':null):el.value;});
  if($('#custom-params')){try{state.config.custom_params=JSON.parse($('#custom-params').value||'{}');}catch{throw new Error('Los parámetros propios deben ser un objeto JSON válido.');}}
  state.config.strategy=$('#strategy-choice').value;state.code=$('#code-editor').value;return {...state.config};
}
function markDirty(){if(state.result){$('#result-stamp').textContent='CAMBIOS SIN EJECUTAR';$('#run-description').textContent='Los resultados visibles corresponden a la última ejecución. Ejecuta de nuevo para aplicar los cambios.';}}
function payload(){if(!state.datasetId)throw new Error('Selecciona un histórico en Datos.');return {dataset_id:state.datasetId,config:readConfig(),code:state.code};}
function getMetric(m,key){if(key==='balance')return m.balance??m.current_balance;if(key==='equity')return m.equity??m.current_equity;return m[key];}
function factor(m){return m?.profit_factor===null && Number(m?.total_trades)>0 ? 'Sin pérdidas' : fmt(m?.profit_factor);}
function kpi(label,value,sub,extra='',featured=false){return `<div class="kpi-card${featured?' featured':''}"><div class="kpi-label">${label}<span data-icon="${featured?'wallet':'info'}"></span></div><div class="kpi-value">${value}</div><div class="kpi-sub">${sub}</div>${extra}</div>`;}
function renderDashboard(){
  const r=state.result,m=r?.metrics||{},cfg=r?.config||state.config,ds=r?.dataset||state.datasets.find(x=>x.id===state.datasetId);
  $('#kpi-grid').innerHTML=[
    kpi('BALANCE DE LA CUENTA',money(getMetric(m,'balance')),`<span class="${signClass(m.net_pnl)}">${money(m.net_pnl,true)}</span><span>resultado neto</span>`,`<div class="kpi-secondary"><span>Patrimonio actual</span><b>${money(getMetric(m,'equity'))}</b></div>`,true),
    kpi('DRAWDOWN MÁXIMO',pct(m.max_drawdown_pct),`${money(m.max_drawdown)} desde el máximo`,`<div class="kpi-secondary"><span>Capital inicial</span><b>${money(cfg.initial_balance)}</b></div>`),
    kpi('FACTOR DE BENEFICIO',factor(m),`Ganancias netas / pérdidas netas`,`<div class="kpi-secondary"><span>Expectativa</span><b class="${signClass(m.expectancy_r)}">${fmt(m.expectancy_r)} R</b></div>`),
    kpi('TASA DE ACIERTO',pct(m.win_rate),`${numeric(m.total_trades)?fmt(m.total_trades,0):'—'} operaciones cerradas`,`<div class="kpi-secondary"><span>Rentabilidad neta</span><b class="${signClass(m.net_return_pct)}">${pct(m.net_return_pct)}</b></div>`)
  ].join('');hydrateIcons($('#kpi-grid'));
  $('#strategy-label').textContent=strategyName(cfg);$('#snapshot-name').textContent=strategyName(cfg);$('#snapshot-description').textContent=description(cfg);
  $('#dataset-label').textContent=ds?`${ds.name}${ds.synthetic?' · SINTÉTICO':''}`:'Sin histórico';$('#period-label').textContent=ds?`${date(cfg.trade_start||ds.start)} — ${date(cfg.trade_end||ds.end)}`:'—';$('#result-stamp').textContent=r?'EJECUCIÓN '+String(r.id).slice(0,6).toUpperCase():'SIN EJECUTAR';
  $('#run-description').textContent=r?`Simulación ${symbolLabel(ds?.symbol)} · ${String(cfg.timeframe).toUpperCase()} · ${ds?.synthetic?'datos sintéticos de demostración':'histórico de '+(ds?.source||'mercado')}.`:'Configura una estrategia. Pon a prueba cada decisión.';
  $('#initial-capital').textContent=money(cfg.initial_balance);$('#dd-caption').textContent=numeric(m.max_drawdown_pct)?'Máx. −'+pct(Math.abs(m.max_drawdown_pct)):'—';
  $('#strategy-snapshot').innerHTML=[['Temporalidad',String(cfg.timeframe||'4h').toUpperCase()],(cfg.sizing_mode==='fixed'?['Tamaño fijo',fmt(cfg.fixed_units,0)+' unidades']:['Riesgo por operación',pct(cfg.risk_pct)]),['Beneficio / riesgo',`1 : ${fmt(cfg.reward_risk,1)}`],['Stop',cfg.stop_mode==='pips'?`${fmt(cfg.stop_pips,1)} pips`:cfg.stop_mode==='percent'?pct(cfg.stop_percent):`ATR × ${fmt(cfg.atr_multiplier,1)}`],['Filtro diario',cfg.daily_filter?'Activado':'Desactivado'],['Semilla',cfg.random_seed??42]].map(([k,v])=>`<div class="parameter-row"><span>${k}</span><b>${esc(v)}</b></div>`).join('');
  const d=r?.diagnostics||{},warnings=r?.warnings||[];let health=[];
  if(!r)health.push(['○','Pendiente de ejecución','El laboratorio mostrará los diagnósticos del motor.',false]);
  else{
    health.push([ds?.synthetic?'!':'✓',ds?.synthetic?'Datos sintéticos':'Origen documentado',ds?.synthetic?'Sirven para probar el laboratorio; no validan rentabilidad histórica.':`${ds?.source||'CSV'} · ${fmt(ds?.rows,0)} velas`,!!ds?.synthetic]);
    health.push(['✓','Costos incluidos',`Comisiones: ${money(m.total_commission)} · swap: ${money(m.total_swap)}`,false]);
    if(d.min_size_skips||d.margin_skips)health.push(['!', 'Entradas omitidas',`${fmt(d.min_size_skips||0,0)} por tamaño mínimo · ${fmt(d.margin_skips||0,0)} por margen.`,true]);
    else health.push(['✓','Ejecución por vela',`${fmt(d.completed_signal_bars,0)} velas de señal · ${fmt(d.ambiguous_exits||0,0)} salidas ambiguas.`,false]);
    if(warnings.length)health.push(['!', `${warnings.length} ${warnings.length===1?'observación':'observaciones'} del motor`,warnings[0],true]);
    if(r.open_position)health.push(['○','Posición abierta','El patrimonio incorpora su valoración al cierre del histórico.',false]);
  }
  $('#run-health').innerHTML=health.map(([mark,title,text,warn])=>`<div class="health-item${warn?' warning':''}"><span>${mark}</span><div><strong>${esc(title)}</strong><p>${esc(text)}</p></div></div>`).join('')+(warnings.length?`<details class="engine-notes"><summary>Ver las ${warnings.length} observaciones del motor</summary><ul>${warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></details>`:'');
  const trades=r?.trades||[];$('#nav-trades').textContent=trades.length||'0';$('#recent-trades').innerHTML=trades.slice(-5).reverse().map(t=>`<tr class="clickable" data-trade="${esc(t.id)}"><td>${date(t.entry_time)}<small>${dateObj(t.entry_time).toISOString().slice(11,16)} UTC</small></td><td>${sideBadge(t.side)}</td><td class="${signClass(t.pnl)}">${money(t.pnl,true)}</td><td class="${signClass(t.r)}">${fmt(t.r)} R</td><td><span class="exit-badge">${esc(exitLabel(t.exit_reason))}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty-row">No hay operaciones cerradas. Revisa el periodo, el calentamiento y el tamaño mínimo.</td></tr>';
  renderAccountCharts();bindTradeRows($('#recent-trades'));
}
function lineChart(target,series,options={}){
  const el=$(target);if(!el)return;const valid=series.map(s=>({...s,data:s.data.filter(p=>numeric(p.value)&&numeric(p.x))})).filter(s=>s.data.length);if(!valid.length){emptyChart(target,options.empty);return;}
  const W=1000,H=options.height||300,L=24,R=78,T=18,B=34,plotW=W-L-R,plotH=H-T-B;
  const all=valid.flatMap(s=>s.data),xmin=Math.min(...all.map(p=>p.x)),xmax=Math.max(...all.map(p=>p.x));let ymin=Math.min(...all.map(p=>p.value)),ymax=Math.max(...all.map(p=>p.value));if(options.zero){ymin=Math.min(0,ymin);ymax=Math.max(0,ymax);}const pad=(ymax-ymin||Math.abs(ymax)*.1||1)*.12;ymin-=options.drawdown?pad*.1:pad;ymax+=options.drawdown?0:pad;
  const X=x=>L+(x-xmin)/(xmax-xmin||1)*plotW,Y=y=>T+(ymax-y)/(ymax-ymin||1)*plotH;
  const yFormat=options.format||((v)=>money(v));const id='gradient-'+target.replace(/\W/g,'');let body=`<defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${options.color||'#80e5d7'}" stop-opacity=".17"/><stop offset="100%" stop-color="${options.color||'#80e5d7'}" stop-opacity=".005"/></linearGradient></defs>`;
  const yticks=options.drawdown?2:4;
  for(let i=0;i<=yticks;i++){const y=ymin+(ymax-ymin)*i/yticks;body+=`<line class="chart-grid" x1="${L}" y1="${Y(y)}" x2="${W-R+4}" y2="${Y(y)}"/><text class="chart-text" x="${W-R+14}" y="${Y(y)+3}">${esc(yFormat(y))}</text>`;}
  for(let i=0;i<=5;i++){const x=xmin+(xmax-xmin)*i/5;body+=`<text class="chart-text" x="${X(x)}" y="${H-9}" text-anchor="${i===0?'start':i===5?'end':'middle'}">${esc(options.xLabel?options.xLabel(x):new Date(x).toLocaleDateString('es',{timeZone:'UTC',month:'short',year:'2-digit'}))}</text>`;}
  if(options.band&&valid.length>=3){const lower=valid[0].data,upper=valid[2].data;body+=`<path d="M${lower.map(p=>`${X(p.x)},${Y(p.value)}`).join('L')}L${[...upper].reverse().map(p=>`${X(p.x)},${Y(p.value)}`).join('L')}Z" fill="#80e5d7" opacity=".11"/>`;}
  valid.forEach((s,index)=>{const path='M'+s.data.map(p=>`${X(p.x).toFixed(2)},${Y(p.value).toFixed(2)}`).join('L');if(index===0&&!options.band&&options.fill!==false){const base=options.drawdown?Y(0):H-B;body+=`<path d="${path}L${X(s.data[s.data.length-1].x)},${base}L${X(s.data[0].x)},${base}Z" fill="url(#${id})"/>`;}body+=`<path d="${path}" fill="none" stroke="${s.color||'#80e5d7'}" stroke-width="${s.width||2}" stroke-linejoin="round" stroke-linecap="round" ${s.dashed?'stroke-dasharray="5 4"':''}/>`;});
  body+=`<line class="chart-crosshair" id="crosshair" x1="0" y1="${T}" x2="0" y2="${H-B}" visibility="hidden"/><rect x="${L}" y="${T}" width="${plotW}" height="${plotH}" fill="transparent" class="chart-hit"/>`;
  el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${esc(options.label||'Curva del resultado')}">${body}</svg><div class="chart-tooltip" hidden></div>`;
  const hit=$('.chart-hit',el),tip=$('.chart-tooltip',el),cross=$('#crosshair',el);hit.addEventListener('pointermove',event=>{const rect=$('svg',el).getBoundingClientRect(),sx=(event.clientX-rect.left)/rect.width*W,x=xmin+((sx-L)/plotW)*(xmax-xmin);const ref=valid[options.band?1:0].data;let nearest=ref[0];for(const p of ref)if(Math.abs(p.x-x)<Math.abs(nearest.x-x))nearest=p;cross.setAttribute('x1',X(nearest.x));cross.setAttribute('x2',X(nearest.x));cross.setAttribute('visibility','visible');tip.hidden=false;tip.innerHTML=`<small>${esc(options.xLabel?`Operación ${fmt(nearest.x,0)}`:date(nearest.x,true))}</small>`+valid.map(s=>{let p=s.data[0];for(const a of s.data)if(Math.abs(a.x-nearest.x)<Math.abs(p.x-nearest.x))p=a;return `${esc(s.name)} <b style="color:${s.color||'#80e5d7'}">${esc(yFormat(p.value))}</b>`;}).join('<br>');tip.style.left=Math.max(8,Math.min(event.clientX-rect.left+12,rect.width-tip.offsetWidth-10))+'px';tip.style.top=Math.max(8,Math.min(event.clientY-rect.top-40,rect.height-tip.offsetHeight))+'px';});
  hit.addEventListener('pointerleave',()=>{tip.hidden=true;cross.setAttribute('visibility','hidden');});
}
function renderAccountCharts(){const curve=state.result?.curve||[];lineChart('#equity-chart',[{name:'Patrimonio',color:'#80e5d7',data:curve.map(p=>({x:stamp(p.time),value:p.equity}))},{name:'Balance',color:'#788b9c',width:1.3,data:curve.map(p=>({x:stamp(p.time),value:p.balance}))}],{label:'Balance y patrimonio de la cuenta en dólares'});lineChart('#drawdown-chart',[{name:'Drawdown',color:'#cf7b86',width:1.4,data:curve.map(p=>({x:stamp(p.time),value:-Math.abs(p.drawdown_pct)}))}],{drawdown:true,zero:true,color:'#cf7b86',height:112,format:v=>`${fmt(v,1)}%`,label:'Drawdown porcentual de la cuenta'});}
function sideBadge(side){const long=['long','buy',1,'1'].includes(side);return `<span class="side-badge ${long?'long':'short'}">${long?'↗ COMPRA':'↘ VENTA'}</span>`;}
function exitLabel(reason){return ({stop_loss:'Stop loss',stop:'Stop loss',sl:'Stop loss',take_profit:'Take profit',tp:'Take profit',break_even:'Break-even',end_of_data:'Fin del histórico',end_of_test:'Fin de prueba',forced:'Cierre final',margin_call:'Margen'}[reason]||reason||'—');}
function bindTradeRows(root){$$('[data-trade]',root).forEach(row=>row.addEventListener('click',()=>{state.selectedTrade=(state.result?.trades||[]).find(t=>String(t.id)===row.dataset.trade);if(state.view==='dashboard'){go('chart');$('#chart-trade-select').value=String(state.selectedTrade?.id||'');renderCandles();}else{renderTradeDetail('#selected-trade-detail',state.selectedTrade);$$('[data-trade]',root).forEach(n=>n.classList.toggle('selected',n===row));}}));}
function renderTrades(){
  const all=state.result?.trades||[];let trades=[...all];const side=$('#filter-side').value,result=$('#filter-result').value,exit=$('#filter-exit').value;
  if(side!=='all')trades=trades.filter(t=>(['long','buy'].includes(t.side)?'long':'short')===side);
  if(result!=='all')trades=trades.filter(t=>result==='win'?t.pnl>0:t.pnl<0);
  if(exit!=='all')trades=trades.filter(t=>t.exit_reason===exit);
  const pageSize=100,pages=Math.max(1,Math.ceil(trades.length/pageSize));state.tradePage=Math.min(state.tradePage||0,pages-1);
  const visible=trades.slice().reverse().slice(state.tradePage*pageSize,(state.tradePage+1)*pageSize);
  $('#trade-count-description').textContent=`${fmt(trades.length,0)} de ${fmt(all.length,0)} operaciones cerradas · haz clic en una fila para inspeccionarla.`;
  $('#all-trades-body').innerHTML=visible.map(t=>`<tr class="clickable" data-trade="${esc(t.id)}"><td>${esc(t.id)}</td><td>${date(t.entry_time,true)}<small>${date(t.exit_time,true)}</small></td><td>${sideBadge(t.side)}</td><td>${fmt(t.entry,5)}<small>${fmt(t.exit,5)}</small></td><td>${fmt(t.sl,5)}<small>${fmt(t.tp,5)}</small></td><td>${fmt(t.lots,3)}</td><td class="${signClass(t.pnl)}">${money(t.pnl,true)}</td><td class="${signClass(t.r)}">${fmt(t.r)}</td><td>${esc(exitLabel(t.exit_reason))}</td></tr>`).join('')||'<tr><td class="empty-row" colspan="9">No hay operaciones para estos filtros.</td></tr>';
  bindTradeRows($('#all-trades-body'));
  const pager=$('#trade-pagination');if(pager){pager.hidden=trades.length<=pageSize;pager.innerHTML=`<span>Mostrando ${fmt(state.tradePage*pageSize+1,0)}–${fmt(Math.min(trades.length,(state.tradePage+1)*pageSize),0)} de ${fmt(trades.length,0)}</span><div><button class="button secondary" id="trade-prev" ${state.tradePage===0?'disabled':''}>← Anterior</button><button class="button secondary" id="trade-next" ${state.tradePage===pages-1?'disabled':''}>Siguiente →</button></div>`;$('#trade-prev').addEventListener('click',()=>{state.tradePage--;renderTrades();});$('#trade-next').addEventListener('click',()=>{state.tradePage++;renderTrades();});}
}
function entryExplanation(t){
  const reason={trend:'Tendencia y ruptura confirmadas',random:'Entrada aleatoria reproducible',custom:'Señal del código Python'}[t.entry_reason]||t.entry_reason||'Señal de estrategia';
  const i=t.entry_indicators||{}, cfg=state.result?.config||{};
  const pieces=[];
  if(numeric(i.ema))pieces.push('EMA '+fmt(i.ema,5));
  if(numeric(i.atr))pieces.push('ATR '+fmt(i.atr,5));
  if(numeric(i.adx))pieces.push('ADX '+fmt(i.adx,1));
  if(numeric(i.plus_di))pieces.push('+DI '+fmt(i.plus_di,1)+' / −DI '+fmt(i.minus_di,1));
  if(cfg.daily_filter&&t.entry_reason==='trend')pieces.push('Tendencia diaria '+(t.side==='long'?'alcista':'bajista'));
  return esc(reason)+(pieces.length?'<br><span class="muted">Indicadores al entrar: '+esc(pieces.join(' · '))+'</span>':'');
}
function renderTradeDetail(target,t){const el=$(target);if(!t){el.innerHTML='';return;}const values=[['Entrada',fmt(t.entry,5)],['Salida',fmt(t.exit,5)],['Stop',fmt(t.sl,5)],['Objetivo',fmt(t.tp,5)],['Resultado neto',money(t.pnl,true)],['Riesgo inicial',money(t.risk_amount)],['Tamaño',`${fmt(t.units,0)} unidades · ${fmt(t.lots,3)} lotes`],['R múltiplo',`${fmt(t.r)} R`],['Comisión',money(t.commission)],['Costo de spread',money(t.spread_cost)],['Costo de slippage',money(t.slippage_cost)],['Swap',money(t.swap_cost)],['MAE · excursión adversa',`${money(t.mae)} · ${fmt(t.mae_r)} R`],['MFE · excursión favorable',`${money(t.mfe)} · ${fmt(t.mfe_r)} R`],['Apertura UTC',date(t.entry_time,true)],['Cierre UTC',date(t.exit_time,true)]];el.innerHTML=`<article class="panel"><div class="panel-heading"><h2>Operación ${esc(t.id)} ${sideBadge(t.side)}</h2><button class="text-button" data-show-chart>Ver en gráfico ↗</button></div><div class="detail-grid">${values.map(([k,v])=>`<div class="detail-cell">${k}<b>${esc(v)}</b></div>`).join('')}</div><div class="detail-notes"><strong>Entrada:</strong> ${entryExplanation(t)}<br><strong>Salida:</strong> ${esc(exitLabel(t.exit_reason))}${t.ambiguous_exit?'<br><span class="loss">Stop y objetivo tocados en la misma vela: se aplicó la resolución conservadora del motor.</span>':''}<br><span class="subtle-note">MAE y MFE son cotas estimadas desde las velas, sin reconstruir el orden intravela. Los costos estimados de spread y slippage ya están incorporados en los precios ejecutados. No deben restarse otra vez al PnL neto.</span></div></article>`;$('[data-show-chart]',el).addEventListener('click',()=>{state.selectedTrade=t;$('#chart-trade-select').value=String(t.id);go('chart');});}
function renderCandles(){
  const all=state.result?.candles||[],t=state.selectedTrade;let candles=all.slice(-110);if(t&&all.length){const i=all.findIndex(c=>stamp(c.time)>=stamp(t.entry_time));const j=all.findIndex(c=>stamp(c.time)>=stamp(t.exit_time));candles=all.slice(Math.max(0,(i<0?all.length-60:i)-30),Math.min(all.length,Math.max(i+40,j+20)));if(candles.length>280){const step=Math.ceil(candles.length/280);candles=candles.filter((_,k)=>k%step===0);}}
  $('#chart-timeframe').textContent=`· ${String(state.result?.config?.timeframe||state.config.timeframe||'4h').toUpperCase()}`;$('#view-chart .panel-heading h2').firstChild.textContent=symbolLabel(state.result?.dataset?.symbol)+' ';renderTradeDetail('#chart-trade-detail',t);if(!candles.length){emptyChart('#candle-chart');return;}
  const W=1100,H=490,L=23,R=93,T=28,B=39,w=W-L-R,h=H-T-B;const emaValues=candles.filter(c=>numeric(c.ema)).map(c=>c.ema);let min=Math.min(...candles.map(c=>c.low),...emaValues),max=Math.max(...candles.map(c=>c.high),...emaValues);if(t){min=Math.min(min,t.sl,t.tp);max=Math.max(max,t.sl,t.tp);}const pad=(max-min)*.13;min-=pad;max+=pad;const X=i=>L+(i+.5)/candles.length*w,Y=v=>T+(max-v)/(max-min||1)*h;let svg='';
  for(let i=0;i<6;i++){const v=min+(max-min)*i/5;svg+=`<line class="chart-grid" x1="${L}" y1="${Y(v)}" x2="${W-R}" y2="${Y(v)}"/><text class="chart-text" x="${W-R+12}" y="${Y(v)+4}">${fmt(v,5)}</text>`;}
  for(let i=0;i<6;i++){const idx=Math.floor((candles.length-1)*i/5);svg+=`<text class="chart-text" x="${X(idx)}" y="${H-13}" text-anchor="${i===0?'start':i===5?'end':'middle'}">${esc(date(candles[idx].time))}</text>`;}
  const cw=Math.max(1.4,w/candles.length*.61);candles.forEach((c,i)=>{const color=c.close>=c.open?'#75cbb2':'#d57884';svg+=`<line x1="${X(i)}" x2="${X(i)}" y1="${Y(c.high)}" y2="${Y(c.low)}" stroke="${color}" stroke-width="1.1"/><rect x="${X(i)-cw/2}" y="${Math.min(Y(c.open),Y(c.close))}" width="${cw}" height="${Math.max(1,Math.abs(Y(c.open)-Y(c.close)))}" fill="${color}"/>`;});
  const ema=candles.map((c,i)=>({i,v:c.ema})).filter(p=>numeric(p.v));if(ema.length)svg+=`<path d="M${ema.map(p=>`${X(p.i)},${Y(p.v)}`).join('L')}" fill="none" stroke="#aaa1ef" stroke-width="1.3"/>`;
  if(t){[['Entrada',t.entry,'#d2d9e2'],['Stop',t.sl,'#ed8893'],['Objetivo',t.tp,'#80e5d7']].forEach(([label,v,color])=>{if(numeric(v))svg+=`<line x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}" stroke="${color}" stroke-width="1" stroke-dasharray="5 5" opacity=".8"/><text x="${L+7}" y="${Y(v)-7}" fill="${color}" font-size="11">${label} ${fmt(v,5)}</text>`;});let i=0;for(let n=0;n<candles.length;n++)if(Math.abs(stamp(candles[n].time)-stamp(t.entry_time))<Math.abs(stamp(candles[i].time)-stamp(t.entry_time)))i=n;svg+=`<circle cx="${X(i)}" cy="${Y(t.entry)}" r="5" fill="#80e5d7" stroke="#172a28" stroke-width="2"/>`;}
  const container=$('#candle-chart');container.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Velas OHLC y niveles de operación">${svg}<rect class="chart-hit" x="${L}" y="${T}" width="${w}" height="${h}" fill="transparent"/></svg><div class="chart-tooltip" hidden></div>`;
  const hit=$('.chart-hit',container),tip=$('.chart-tooltip',container);hit.addEventListener('pointermove',event=>{const rect=$('svg',container).getBoundingClientRect();const x=(event.clientX-rect.left)/rect.width*W;const c=candles[Math.max(0,Math.min(candles.length-1,Math.floor((x-L)/w*candles.length)))];tip.hidden=false;tip.innerHTML=`<small>${esc(date(c.time,true))} UTC</small>Apertura <b>${fmt(c.open,5)}</b><br>Máximo ${fmt(c.high,5)}<br>Mínimo ${fmt(c.low,5)}<br>Cierre <b>${fmt(c.close,5)}</b><br>EMA ${fmt(c.ema,5)}`;tip.style.left=Math.max(5,Math.min(event.clientX-rect.left+13,rect.width-tip.offsetWidth-5))+'px';tip.style.top='20px';});hit.addEventListener('pointerleave',()=>tip.hidden=true);
  $('#candle-caption').textContent=`${fmt(candles.length,0)} velas visibles${state.result?.diagnostics?.candles_sampled?' · muestra del histórico completo':''} · ${date(candles[0].time)} — ${date(candles[candles.length-1].time)} · ${t?'Niveles de la operación '+t.id:'Selecciona una operación para inspeccionar sus niveles.'}`;
}
function setResult(result,loadConfig=true){state.result=result;state.selectedTrade=null;state.tradePage=0;state.mc=null;state.datasetId=result.dataset?.id||state.datasetId;if(loadConfig){state.config={...state.defaults,...result.config};state.code=result.code||state.defaultCode;renderConfig();}renderHeader();renderDashboard();renderDatasets();$('#chart-trade-select').innerHTML='<option value="">Últimas velas</option>'+(result.trades||[]).slice().reverse().map(t=>`<option value="${esc(t.id)}">#${esc(t.id)} · ${date(t.entry_time)} · ${money(t.pnl,true)}</option>`).join('');$('#filter-exit').innerHTML='<option value="all">Todas</option>'+[...new Set((result.trades||[]).map(t=>t.exit_reason))].map(reason=>`<option value="${esc(reason)}">${esc(exitLabel(reason))}</option>`).join('');renderTrades();renderCandles();emptyChart('#mc-chart','Simula escenarios a partir de esta ejecución.');$('#mc-metrics').innerHTML='';$('#mc-note').textContent='Remuestreo de operaciones cerradas. La simulación no reproduce nuevos regímenes de mercado.';if(state.view==='dashboard')renderAccountCharts();}
function renderHeader(){const ds=state.datasets.find(d=>d.id===state.datasetId)||state.result?.dataset;$('#market-symbol').textContent=symbolLabel(ds?.symbol);$('#market-description').textContent='Cuenta en USD · ejecución simulada';$('#top-timeframe').textContent=String(state.config.timeframe||'4h').toUpperCase();$('#data-status').classList.toggle('real',!!ds&&!ds.synthetic);$('#data-status').innerHTML=`<i></i>${ds?(ds.synthetic?'DEMO · DATOS SINTÉTICOS':'HISTÓRICO · '+esc(ds.source||'CSV')):'SIN HISTÓRICO'}`;}
function renderDatasets(){const rows=state.datasets;$('#dataset-count').textContent=`${rows.length} HISTÓRICO${rows.length===1?'':'S'}`;$('#datasets-list').innerHTML=rows.map(ds=>`<div class="dataset-item${ds.id===state.datasetId?' selected':''}"><div class="dataset-icon">${icon('database')}</div><div class="dataset-info"><strong>${esc(ds.name)}</strong><p>${esc(symbolLabel(ds.symbol))} · ${esc(ds.source)} · ${fmt(ds.rows,0)} velas · ${esc(String(ds.timeframe||'').toUpperCase())}<br>${date(ds.start)} — ${date(ds.end)} · ${esc(ds.price_type||'precio no especificado')}${ds.quality?.unexpected_missing_bars?` · ${fmt(ds.quality.unexpected_missing_bars,0)} intervalos faltantes fuera de fin de semana`:''}</p></div><span class="tag">${ds.synthetic?'SINTÉTICO':'DATOS IMPORTADOS'}</span><button class="button ${ds.id===state.datasetId?'secondary':'primary'}" data-select-dataset="${esc(ds.id)}">${ds.id===state.datasetId?'Seleccionado':'Seleccionar'}</button></div>`).join('')||'<div class="empty-state">Importa un CSV o descarga un histórico para empezar.</div>';$$('[data-select-dataset]').forEach(el=>el.addEventListener('click',()=>{state.datasetId=el.dataset.selectDataset;renderDatasets();renderHeader();markDirty();status('Histórico seleccionado. Ejecuta el backtest para aplicar el cambio.');}));}
async function refreshDatasets(){state.datasets=await api('/api/datasets');renderDatasets();renderHeader();}
function renderExperiments(){const list=state.experiments;$('#experiment-count').textContent=`${list.length} EXPERIMENTO${list.length===1?'':'S'}`;$('#experiments-list').innerHTML=list.map(item=>`<div class="experiment-item"><div><h3>${esc(item.name)}</h3><p>${esc(item.hypothesis||'Sin hipótesis registrada.')}</p><small>${date(item.created_at,true)} UTC · ${esc(strategyName(item.config))} · ${esc(symbolLabel(item.dataset?.symbol))} ${esc(String(item.config?.timeframe||'').toUpperCase())} · ${item.dataset?.synthetic?'SINTÉTICO':'HISTÓRICO'}</small></div><span class="experiment-result ${signClass(item.metrics?.net_pnl)}">${money(item.metrics?.net_pnl,true)}</span><button class="button secondary" data-load-experiment="${esc(item.id)}">Abrir ↗</button></div>`).join('')||`<div class="empty-state">${icon('flask')}Guarda tu primera ejecución para conservar la hipótesis y compararla después.</div>`;$$('[data-load-experiment]').forEach(el=>el.addEventListener('click',()=>task(el,'Abriendo experimento…',async()=>{const r=await api('/api/experiments/'+el.dataset.loadExperiment);setResult(r);go('dashboard');status('Experimento abierto: '+r.name);})));for(const id of ['compare-a','compare-b']){const prev=$('#'+id).value;$('#'+id).innerHTML=list.length?list.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join(''):'<option value="">Guarda al menos dos experimentos</option>';if(list.some(r=>r.id===prev))$('#'+id).value=prev;}if(list.length>1&&$('#compare-a').value===$('#compare-b').value)$('#compare-b').selectedIndex=1;}
function downloadFile(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function requireResult(){if(!state.result)throw new Error('Ejecuta primero un backtest.');return state.result;}
function renderMC(mc){const terminal=mc.terminal||{},dd=mc.max_drawdown_pct||{};$('#mc-metrics').innerHTML=kpi('BALANCE FINAL · MEDIANA',money(terminal.p50),`P5 ${money(terminal.p5)} · P95 ${money(terminal.p95)}`)+kpi('PROBABILIDAD DE PÉRDIDA',pct(mc.probability_loss_pct),`${fmt(mc.simulations,0)} simulaciones · semilla ${esc(mc.seed)}`)+kpi('DRAWDOWN · PERCENTIL 95',pct(dd.p95),`Mediana ${pct(dd.p50)} · ruina ${pct(mc.probability_ruin_pct)}`);hydrateIcons($('#mc-metrics'));$('#mc-note').textContent=[({bootstrap_net_r_compounded:"Remuestreo de R con riesgo compuesto",bootstrap_fixed_net_pnl:"Remuestreo de resultados en USD con tamaño fijo"}[mc.method]||"Remuestreo de operaciones"),...(mc.warnings||[])].filter(Boolean).join(' · ')||'Remuestreo de operaciones históricas; no incorpora cambios futuros de régimen.';const curves=mc.curves||[];lineChart('#mc-chart',[{name:'P5',color:'#567a71',width:1,data:curves.map(p=>({x:p.trade,value:p.p5}))},{name:'Mediana',color:'#80e5d7',width:2,data:curves.map(p=>({x:p.trade,value:p.p50}))},{name:'P95',color:'#567a71',width:1,data:curves.map(p=>({x:p.trade,value:p.p95}))}],{band:true,fill:false,xLabel:x=>fmt(x,0),label:'Monte Carlo: percentiles 5, 50 y 95'});}
function renderComparison(a,b){$('#compare-name-a').textContent=a.name||'EXPERIMENTO A';$('#compare-name-b').textContent=b.name||'EXPERIMENTO B';lineChart('#compare-chart',[{name:a.name||'A',color:'#80e5d7',data:(a.curve||[]).map(p=>({x:stamp(p.time),value:p.equity}))},{name:b.name||'B',color:'#aaa1ef',data:(b.curve||[]).map(p=>({x:stamp(p.time),value:p.equity}))}],{fill:false,label:'Comparación del patrimonio de dos experimentos'});const rows=[['Capital inicial',money(a.config.initial_balance),money(b.config.initial_balance)],['Resultado neto',money(a.metrics.net_pnl,true),money(b.metrics.net_pnl,true)],['Rentabilidad',pct(a.metrics.net_return_pct),pct(b.metrics.net_return_pct)],['Drawdown máximo',pct(a.metrics.max_drawdown_pct),pct(b.metrics.max_drawdown_pct)],['Factor de beneficio',factor(a.metrics),factor(b.metrics)],['Acierto',pct(a.metrics.win_rate),pct(b.metrics.win_rate)],['Expectativa',fmt(a.metrics.expectancy_r)+' R',fmt(b.metrics.expectancy_r)+' R'],['Operaciones',fmt(a.metrics.total_trades,0),fmt(b.metrics.total_trades,0)],['Estrategia',strategyName(a.config),strategyName(b.config)],['Histórico',a.dataset?.name,b.dataset?.name],['Temporalidad',a.config.timeframe,b.config.timeframe],['Riesgo (%)',fmt(a.config.risk_pct),fmt(b.config.risk_pct)]];$('#compare-table').innerHTML=rows.map(row=>`<tr>${row.map((v,i)=>i?`<td>${esc(v)}</td>`:`<td><strong>${esc(v)}</strong></td>`).join('')}</tr>`).join('');if(a.dataset?.id!==b.dataset?.id||a.config.initial_balance!==b.config.initial_balance)status('La comparación usa diferentes históricos o capitales iniciales; interpreta también los porcentajes.');}
async function pollJob(id,onProgress){for(;;){const job=await api('/api/jobs/'+id);onProgress?.(job);if(['completed','complete','done'].includes(job.status))return job;if(['failed','error'].includes(job.status))throw new Error(job.error||job.message||'La tarea no se completó.');await new Promise(resolve=>setTimeout(resolve,1100));}}
function addResearchControls(){
  $('#view-robustness').insertAdjacentHTML('beforeend',`<div class="two-columns"><article class="panel"><div class="panel-heading"><h2>Sensibilidad de parámetros</h2><span class="mini-label">EXPLORATORIA</span></div><div class="form-body"><div class="form-row"><label>Múltiplos ATR, separados por coma<input id="sensitivity-atr" value="1.5, 2, 2.5"></label><label>Ventanas de ruptura, separadas por coma<input id="sensitivity-breakout" value="10, 20, 30"></label></div><button class="button secondary" id="run-sensitivity">Medir sensibilidad</button><p id="sensitivity-note" class="form-help">Busca estabilidad entre valores vecinos. El máximo retrospectivo no demuestra una ventaja.</p></div><div class="table-scroll"><table><thead><tr><th>ATR</th><th>RUPTURA</th><th>PNL NETO</th><th>DRAWDOWN</th></tr></thead><tbody id="sensitivity-results"><tr><td colspan="4" class="empty-row">Sin ejecutar</td></tr></tbody></table></div></article><article class="panel"><div class="panel-heading"><h2>Prueba fuera de muestra</h2><span class="mini-label">CRONOLÓGICA</span></div><div class="form-body"><label>Porcentaje inicial de desarrollo<input id="holdout-split" type="number" min="50" max="90" value="70" step="5"></label><p class="form-help">Congela la configuración actual, observa el primer periodo y después revela el tramo reservado. Conserva el calentamiento de indicadores.</p><div class="form-row"><button class="button secondary" id="prepare-holdout">Congelar y evaluar desarrollo</button><button class="button primary" id="reveal-holdout" disabled>Revelar tramo reservado</button></div><p id="holdout-note" class="form-help">Una división temporal no elimina el sesgo si ya inspeccionaste todo el histórico.</p></div><div class="table-scroll"><table><thead><tr><th>PERIODO</th><th>PNL NETO</th><th>DRAWDOWN</th><th>OPERACIONES</th></tr></thead><tbody id="holdout-results"><tr><td colspan="4" class="empty-row">Sin preparar</td></tr></tbody></table></div></article></div>`);
  $('#run-sensitivity').addEventListener('click',event=>task(event.currentTarget,'Midiendo estabilidad entre parámetros…',async()=>{const atr=$('#sensitivity-atr').value.split(',').map(v=>Number(v.trim())),breakout=$('#sensitivity-breakout').value.split(',').map(v=>Number(v.trim()));const job=await api('/api/sensitivity',{...payload(),atr_values:atr,breakout_values:breakout});const done=await pollJob(job.job_id,j=>$('#sensitivity-note').textContent=j.message||`${j.progress}%`);$('#sensitivity-note').textContent=done.result.note;$('#sensitivity-results').innerHTML=done.result.cells.map(c=>`<tr><td>${fmt(c.atr_multiplier,1)}</td><td>${fmt(c.breakout_period,0)}</td><td class="${signClass(c.metrics.net_pnl)}">${money(c.metrics.net_pnl,true)}</td><td>${pct(c.metrics.max_drawdown_pct)}</td></tr>`).join('');}));
  $('#prepare-holdout').addEventListener('click',event=>task(event.currentTarget,'Congelando reglas y evaluando el periodo de desarrollo…',async()=>{state.holdout=await api('/api/holdout',{...payload(),split:Number($('#holdout-split').value)/100});renderHoldout(state.holdout);$('#reveal-holdout').disabled=false;status('Reglas congeladas para esta prueba. Puedes revelar el tramo reservado cuando termines de revisar el desarrollo.');}));
  $('#reveal-holdout').addEventListener('click',event=>task(event.currentTarget,'Evaluando el tramo reservado con las reglas congeladas…',async()=>{if(!state.holdout)throw new Error('Prepara primero la división temporal.');state.holdout=await api('/api/holdout/reveal',{ticket_id:state.holdout.ticket_id});renderHoldout(state.holdout);status('Tramo reservado revelado. Las reglas aplicadas son las congeladas al preparar la prueba.');}));
}
function renderHoldout(r){$('#holdout-note').textContent=`Corte: ${date(r.boundary)}. ${r.note||''}`;$('#holdout-results').innerHTML=[['Desarrollo',r.train],['Reservado',r.test]].map(([label,result])=>result?`<tr><td>${label}</td><td class="${signClass(result.metrics.net_pnl)}">${money(result.metrics.net_pnl,true)}</td><td>${pct(result.metrics.max_drawdown_pct)}</td><td>${fmt(result.metrics.total_trades,0)}</td></tr>`:`<tr><td>${label}</td><td colspan="3">Oculto hasta revelar</td></tr>`).join('');}
function addFlexibleControls(){
  $('#strategy-choice').closest('.form-body').insertAdjacentHTML('afterbegin',`<label style="margin-bottom:16px">Plantilla editable<select id="strategy-preset"><option value="">Tu configuración actual</option><option value="null">Null · entradas aleatorias</option><option value="v1">Trend V1 · tendencia simple</option><option value="v2">Trend V2 · tendencia y ruptura</option><option value="a">A · base: sin diario, ADX, margen ni BE</option><option value="b">B · añadir filtro diario</option><option value="c">C · añadir ADX</option><option value="d">D · añadir margen de ruptura 0,1 ATR</option><option value="e">E · añadir break-even desde 1,5 R</option></select></label>`);
  $('#strategy-preset').addEventListener('change',event=>{const patches={null:{strategy:'random'},v1:{strategy:'trend',daily_filter:false,adx_filter:false,ema_filter:true,breakout_period:10},v2:{strategy:'trend',daily_filter:true,adx_filter:true,ema_filter:true,breakout_period:20,reward_risk:3,break_even_r:1.5},a:{strategy:"trend",daily_filter:false,adx_filter:false,breakout_atr_buffer:0,break_even_r:0},b:{strategy:"trend",daily_filter:true,adx_filter:false,breakout_atr_buffer:0,break_even_r:0},c:{strategy:"trend",daily_filter:true,adx_filter:true,breakout_atr_buffer:0,break_even_r:0},d:{strategy:"trend",daily_filter:true,adx_filter:true,breakout_atr_buffer:0.1,break_even_r:0},e:{strategy:"trend",daily_filter:true,adx_filter:true,breakout_atr_buffer:0.1,break_even_r:1.5}};const patch=patches[event.target.value];if(!patch)return;readConfig();for(const [key,value]of Object.entries(patch))if(key in state.config)state.config[key]=value;renderConfig();markDirty();status('Plantilla aplicada. Todos los valores permanecen editables.');});
  const pairs=['EURUSD','GBPUSD','AUDUSD','NZDUSD','USDJPY','USDCAD','USDCHF'];const pairSelect=id=>`<label style="margin-bottom:16px">Par de divisas<select id="${id}">${pairs.map(p=>`<option value="${p}">${symbolLabel(p)}</option>`).join('')}</select></label>`;
  $('#csv-name').closest('.form-body').insertAdjacentHTML('afterbegin',pairSelect('csv-symbol'));$('#download-start').closest('.form-body').insertAdjacentHTML('afterbegin',pairSelect('download-symbol'));$('#download-start').closest('.panel').querySelector('.panel-heading p').textContent='Velas históricas reales · pares principales';$('#download-end').closest('label').firstChild.textContent='Hasta (fecha exclusiva)';$('#csv-price-type option[value="bidask"]').value='bid_ask';
}
function setup(){
  $('#all-trades-body').closest('.panel').insertAdjacentHTML('beforeend','<div class="trade-pagination" id="trade-pagination" hidden></div>');
  $('.code-panel').insertAdjacentHTML('beforeend','<div class="code-validation"><span>Comprueba la sintaxis y las reglas permitidas.</span><button class="button secondary" id="validate-code">Validar código</button></div>');
  $('#validate-code').addEventListener('click',event=>task(event.currentTarget,'Validando el código de señales…',async()=>{await api('/api/validate-code',{code:$('#code-editor').value});status('Código válido. La ejecución del backtest comprobará las señales sobre los datos.');}));
  hydrateIcons();addFlexibleControls();addResearchControls();$$('[data-view]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.view)));$$('[data-go]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.go)));$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));document.addEventListener('click',e=>{if(innerWidth<761&&!e.target.closest('.sidebar')&&!e.target.closest('#menu-toggle'))$('#sidebar').classList.remove('open');});
  $('#strategy-choice').addEventListener('change',e=>{state.config.strategy=e.target.value;$('#strategy-explanation').textContent=description(state.config);markDirty();});$('#code-editor').addEventListener('input',markDirty);$('#code-editor').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('    ',start,end,'end');}});
  $('#code-example').addEventListener('change',e=>{const examples={default:state.defaultCode,momentum:'def signal(ctx):\n    if not ctx["ready"]:\n        return 0\n    close = ctx["close"][-1]\n    previous = ctx["close"][-2]\n    if close > previous and close > ctx["ema"][-1]:\n        return 1\n    if close < previous and close < ctx["ema"][-1]:\n        return -1\n    return 0\n',contrarian:'def signal(ctx):\n    if not ctx["ready"]:\n        return 0\n    close = ctx["close"][-1]\n    ema = ctx["ema"][-1]\n    atr = ctx["atr"][-1]\n    if close < ema - 2 * atr:\n        return 1\n    if close > ema + 2 * atr:\n        return -1\n    return 0\n'};if(examples[e.target.value]){$('#code-editor').value=examples[e.target.value];state.code=examples[e.target.value];state.config.strategy='custom';$('#strategy-choice').value='custom';$('#strategy-explanation').textContent=description(state.config);markDirty();}e.target.value='';});
  $('#reset-config').addEventListener('click',()=>{state.config={...state.defaults};state.code=state.defaultCode;renderConfig();markDirty();status('Parámetros iniciales restaurados. Ejecuta para aplicar.');});
  $('#run-backtest').addEventListener('click',event=>task(event.currentTarget,'Simulando señales, ejecución y costos…',async()=>{const result=await api('/api/backtest',payload());setResult(result);go('dashboard');status(`Backtest completado: ${fmt(result.metrics.total_trades,0)} operaciones cerradas. ${result.dataset?.synthetic?'Datos sintéticos: resultado de demostración.':''}`);}));
  $('#save-top').addEventListener('click',()=>{go('experiments');$('#experiment-name').focus();});$('#save-experiment').addEventListener('click',event=>task(event.currentTarget,'Guardando la instantánea del experimento…',async()=>{const r=requireResult(),name=$('#experiment-name').value.trim();if(!name)throw new Error('Escribe un nombre para el experimento.');await api('/api/experiments',{result_id:r.id,name,hypothesis:$('#experiment-hypothesis').value.trim()});state.experiments=await api('/api/experiments');renderExperiments();status('Experimento guardado en esta computadora.');}));
  $('#export-report').addEventListener('click',event=>task(event.currentTarget,'Preparando informe…',async()=>{const r=requireResult();downloadFile('forex-lab-'+r.id.slice(0,8)+'.json',JSON.stringify(r,null,2),'application/json');status('Informe completo exportado como JSON.');}));$('#export-trades').addEventListener('click',event=>task(event.currentTarget,'Preparando registro de operaciones…',async()=>{const r=requireResult(),trades=r.trades||[];if(!trades.length)throw new Error('No hay operaciones cerradas para exportar.');const keys=Object.keys(trades[0]);const cell=v=>`"${String(v??'').replace(/"/g,'""')}"`;downloadFile('operaciones-'+r.id.slice(0,8)+'.csv','\uFEFF'+[keys.join(','),...trades.map(t=>keys.map(k=>cell(t[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');status('Registro CSV exportado.');}));
  ['filter-side','filter-result','filter-exit'].forEach(id=>$('#'+id).addEventListener('change',()=>{state.tradePage=0;renderTrades();}));$('#chart-trade-select').addEventListener('change',e=>{state.selectedTrade=(state.result?.trades||[]).find(t=>String(t.id)===e.target.value)||null;renderCandles();});
  $('#run-monte-carlo').addEventListener('click',event=>task(event.currentTarget,'Calculando escenarios Monte Carlo…',async()=>{const r=requireResult();state.mc=await api('/api/monte-carlo',{result_id:r.id,simulations:Number($('#mc-simulations').value),seed:Number($('#mc-seed').value)});renderMC(state.mc);}));
  $('#run-research').addEventListener('click',event=>task(event.currentTarget,'Comparando configuración, costos y referencia aleatoria…',async()=>{const r=await api('/api/research',payload());state.research=r;$('#research-status').textContent='COMPLETADO';$('#research-note').textContent=r.note||'';$('#research-results').innerHTML=r.runs.map(run=>`<tr><td><strong>${esc(run.label)}</strong></td><td class="${signClass(run.metrics.net_pnl)}">${money(run.metrics.net_pnl,true)}</td><td>${pct(run.metrics.max_drawdown_pct)}</td><td>${factor(run.metrics)}</td><td>${fmt(run.metrics.total_trades,0)}</td><td><button class="text-button" data-research-id="${esc(run.result_id)}">Abrir ↗</button></td></tr>`).join('');$$('[data-research-id]').forEach(button=>button.addEventListener('click',()=>task(button,'Abriendo escenario…',async()=>{setResult(await api('/api/results/'+button.dataset.researchId));go('dashboard');})));}));
  $('#compare-runs').addEventListener('click',event=>task(event.currentTarget,'Comparando ejecuciones guardadas…',async()=>{const a=$('#compare-a').value,b=$('#compare-b').value;if(!a||!b||a===b)throw new Error('Selecciona dos experimentos distintos.');state.comparison=await Promise.all([api('/api/experiments/'+a),api('/api/experiments/'+b)]);renderComparison(...state.comparison);}));
  $('#refresh-data').addEventListener('click',event=>task(event.currentTarget,'Actualizando biblioteca de históricos…',refreshDatasets));$('#csv-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;if(file.size>90*1024*1024){status('El CSV debe ser menor de 90 MB. Divide el histórico.','error');return;}state.csv=await file.text();if(!$('#csv-name').value)$('#csv-name').value=file.name.replace(/\.csv$/i,'');status('CSV leído. Completa su origen de precio y pulsa Importar histórico.');});
  $('#import-csv').addEventListener('click',event=>task(event.currentTarget,'Validando e importando el histórico…',async()=>{if(!state.csv)throw new Error('Selecciona primero un archivo CSV.');const ds=await api('/api/import',{content:state.csv,name:$('#csv-name').value.trim()||'Histórico CSV',symbol:$('#csv-symbol').value,price_type:$('#csv-price-type').value,spread_pips:Number($('#csv-spread').value)});state.datasetId=ds.id;await refreshDatasets();markDirty();status(`Histórico importado: ${fmt(ds.rows,0)} velas. Ejecuta el backtest para usarlo.`);}));
  $('#download-data').addEventListener('click',event=>task(event.currentTarget,'Iniciando descarga del proveedor…',async()=>{const job=await api('/api/download',{start:$('#download-start').value,end:$('#download-end').value,symbol:$('#download-symbol').value});$('#download-progress').hidden=false;const done=await pollJob(job.job_id,j=>{$('#download-progress .progress-track i').style.width=Math.max(1,Math.min(100,j.progress||0))+'%';$('#download-progress p').textContent=j.message||'Descargando…';});if(done.dataset)state.datasetId=done.dataset.id;await refreshDatasets();markDirty();status('Histórico descargado y seleccionado. Ya puedes ejecutar el backtest.');}));
  $('#code-contract').textContent='Series: time, open, high, low, close, ema, atr, adx, plus_di y minus_di. También: ready, daily_bull, daily_bear, breakout_up, breakout_down y params. La última posición [-1] es la vela cerrada más reciente.';
  $('#research-results').innerHTML='<tr><td colspan="6" class="empty-row">Ejecuta las pruebas para comparar escenarios calculados.</td></tr>';
  emptyChart('#mc-chart','Simula escenarios después de ejecutar un backtest.');emptyChart('#compare-chart','Guarda y selecciona dos experimentos para compararlos.');$('#compare-table').innerHTML='<tr><td colspan="3" class="empty-row">Todavía no hay una comparación.</td></tr>';
}
async function boot(){setup();status('Cargando el laboratorio local…','busy');try{const initial=await api('/api/bootstrap');state.defaults={...initial.config};state.config={...initial.config};state.defaultCode=initial.code||'';state.code=state.defaultCode;state.datasets=initial.datasets||[];state.experiments=initial.experiments||[];state.datasetId=initial.last_result?.dataset?.id||state.datasets[0]?.id||null;renderConfig();renderDatasets();renderExperiments();if(initial.last_result)setResult(initial.last_result);else{renderHeader();renderDashboard();renderTrades();}go(location.hash.slice(1)||'dashboard');status('');}catch(error){renderDashboard();status('No se pudo iniciar el laboratorio: '+error.message,'error');}}
boot();



